import sys
import math

def calculate_distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def find_closest_seats(tram, passengers):
    R = len(tram)
    C = len(tram[0])
    explosions = 0

    while passengers:
        min_distance = float('inf')
        closest_seats = []

        for px, py in passengers:
            for rx in range(R):
                for cx in range(C):
                    if tram[rx][cx] == 'L':
                        distance = calculate_distance(px, py, rx, cx)
                        if distance < min_distance:
                            min_distance = distance
                            closest_seats = [(rx, cx)]
                        elif distance == min_distance:
                            closest_seats.append((rx, cx))

        if len(closest_seats) > 1:
            explosions += 1

        for seat in closest_seats:
            tram[seat[0]][seat[1]] = 'X'

        passengers = [(px, py) for px, py in passengers if tram[px][py] != 'X']

    return explosions

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    R = int(data[0])
    C = int(data[1])
    tram = [list(data[i + 2]) for i in range(R)]

    passengers = [(r, c) for r in range(R) for c in range(C) if tram[r][c] == 'X']

    result = find_closest_seats(tram, passengers)
    print(result)

if __name__ == "__main__":
    main()
